70	function H=physical_left_hamiltonian(spin_system)
71	% Reproduce the isotropic left-product Hamiltonian from the system tensors.
72	nspins=spin_system.comp.nspins;
73	H=0*operator(spin_system,'E',1,'left');
74	
75	for n=1:nspins
76	    omega=trace(spin_system.inter.zeeman.matrix{n})/3;
77	    H=H+omega*operator(spin_system,'Lz',n,'left');
78	end
79	
80	axes={'Lx','Ly','Lz'};
81	for n=1:nspins
82	    for k=(n+1):nspins
83	        if isempty(spin_system.inter.coupling.matrix{n,k}), continue; end
84	        coupling=trace(spin_system.inter.coupling.matrix{n,k})/3;
85	        for a=1:numel(axes)
86	            H=H+coupling*operator(spin_system,{axes{a},axes{a}},...
87	                                  {n,k},'left');
88	        end
89	    end
90	end
91	end
