93	function answer=category(value)
94	if ~isfinite(value)
95	    answer='nonfinite';
96	elseif value<1e-8
97	    answer='small';
98	elseif value<1e-2
99	    answer='moderate';
100	else
101	    answer='large';
102	end
103	end
