1	function spin_system=task015_public_system(formalism)
2	% Four-spin fluorine subsystem adapted from the bundled tetrafluoroglucose
3	% example. The small system keeps the offline scientific run deterministic.
4	sys.magnet=9.4;
5	sys.isotopes={'19F','19F','19F','19F'};
6	
7	inter.zeeman.scalar={-120.5380 -133.9429 -129.3169 -129.5320};
8	inter.coupling.scalar=cell(4,4);
9	inter.coupling.scalar{1,2}= 271.2924;
10	inter.coupling.scalar{3,4}= 271.2924;
11	inter.coupling.scalar{1,3}=   0.5401;
12	inter.coupling.scalar{1,4}= -25.9884;
13	inter.coupling.scalar{2,3}=   9.9625;
14	inter.coupling.scalar{2,4}= -40.7675;
15	
16	inter.relaxation={'damp'};
17	inter.equilibrium='zero';
18	inter.temperature=40;
19	inter.damp_rate=5.0;
20	inter.rlx_keep='diagonal';
21	
22	sys.output='hush';
23	sys.disable={'hygiene','pt','zte','dss','trajlevel','merge'};
24	sys.enable={};
25	
26	bas.formalism=formalism;
27	bas.approximation='none';
28	
29	spin_system=create(sys,inter);
30	spin_system=basis(spin_system,bas);
31	end
